(() => {
  'use strict';

  // ── Phone normalisation / validation ──────────────────────
  // Accepts common US formats and international +1 variants.
  // Strips everything non-digit, then checks for 10 digits (domestic)
  // or 11 digits starting with 1 (E.164-ish).
  function isValidPhone(value) {
    const digits = value.replace(/\D/g, '');
    return digits.length === 10 || (digits.length === 11 && digits[0] === '1');
  }

  // ── Validation rules ──────────────────────────────────────
  const rules = {
    'full-name': (val) => {
      if (!val.trim()) return 'Error: Full name is required.';
      if (val.trim().length < 2) return 'Error: Enter your full name (at least 2 characters).';
      return null;
    },
    email: (val) => {
      if (!val.trim()) return 'Error: Email address is required.';
      // Basic email shape check; browser type="email" also validates.
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim()))
        return 'Error: Enter a valid email address, e.g. name@example.com.';
      return null;
    },
    phone: (val) => {
      if (!val.trim()) return null; // optional
      if (!isValidPhone(val))
        return 'Error: Enter a valid phone number, e.g. (555) 123-4567 or +1 555 123 4567.';
      return null;
    },
  };

  // ── DOM refs ──────────────────────────────────────────────
  const form = document.getElementById('contact-form');
  const formStatus = document.getElementById('form-status');
  const successBanner = document.getElementById('success-message');

  function getField(name) {
    return document.getElementById(name);
  }
  function getError(name) {
    return document.getElementById(`${name}-error`);
  }

  // ── Apply / clear error on a single field ─────────────────
  function setError(name, message) {
    const input = getField(name);
    const errorEl = getError(name);
    if (!input || !errorEl) return;

    if (message) {
      errorEl.textContent = message;
      errorEl.hidden = false;
      input.setAttribute('aria-invalid', 'true');
    } else {
      errorEl.textContent = '';
      errorEl.hidden = true;
      input.removeAttribute('aria-invalid');
    }
  }

  // ── Validate a single field and return error or null ──────
  function validateField(name) {
    const input = getField(name);
    if (!input) return null;
    const rule = rules[name];
    return rule ? rule(input.value) : null;
  }

  // ── Blur handler: validate on leave ───────────────────────
  function handleBlur(event) {
    const name = event.target.name;
    if (!rules[name]) return;
    const error = validateField(name);
    setError(name, error);
  }

  // ── Input handler: clear error once fixed ─────────────────
  function handleInput(event) {
    const name = event.target.name;
    if (!rules[name]) return;
    // Only clear if currently showing an error and the field is now valid
    const input = getField(name);
    if (input && input.getAttribute('aria-invalid') === 'true') {
      const error = validateField(name);
      setError(name, error);
    }
  }

  // ── Submit handler ────────────────────────────────────────
  function handleSubmit(event) {
    event.preventDefault();

    const fieldNames = ['full-name', 'email', 'phone'];
    let firstInvalid = null;

    fieldNames.forEach((name) => {
      const error = validateField(name);
      setError(name, error);
      if (error && !firstInvalid) firstInvalid = getField(name);
    });

    if (firstInvalid) {
      // Move focus to first invalid field so keyboard/SR users land there.
      firstInvalid.focus();
      // Announce error count via the hidden status region (no double-announce with focus).
      const errorCount = fieldNames.filter((n) => validateField(n)).length;
      formStatus.textContent = `${errorCount} error${errorCount > 1 ? 's' : ''} found. Please correct the highlighted field${errorCount > 1 ? 's' : ''}.`;
      return;
    }

    // ── Simulate async submission ──────────────────────────
    const submitBtn = form.querySelector('button[type="submit"]');
    submitBtn.disabled = true;
    submitBtn.textContent = 'Sending…';

    setTimeout(() => {
      // Hide form, show success banner, announce to SR.
      form.hidden = true;
      successBanner.hidden = false;
      formStatus.textContent = 'Message sent. We will reply within 24 hours.';
      // Move focus to the banner heading area for context.
      successBanner.setAttribute('tabindex', '-1');
      successBanner.focus();
    }, 800);
  }

  // ── Wire up events ────────────────────────────────────────
  form.addEventListener('submit', handleSubmit);

  Object.keys(rules).forEach((name) => {
    const input = getField(name);
    if (!input) return;
    input.addEventListener('blur', handleBlur);
    input.addEventListener('input', handleInput);
  });
})();

